input('edit-image').addEventListener('click',()=>{cancel();try{const image=controller?.imageForEdit();if(!image)throw Error('Select an image layer first');stageImage(image.source,image.placement,{replace:true});}catch(error){say('Image: '+error.message);}});
input('surface-image').addEventListener('click',()=>{cancel();const s=imageStage;if(!s)return;controller?.clearImagePreview();s.surface=!s.surface;s.frame=null;s.mode='move';if(s.surface){s.overlay?.dispose();s.overlay=null;s.guide=createSurfaceImageGuide(bridge().scene,s.source);}else{s.guide?.dispose();s.guide=null;s.overlay=createPaintImageOverlay(canvas,s.source);}drawImageStage();imageHint();});
input('image-mode').addEventListener('click',()=>{cancel();if(imageStage){imageStage.mode=cyclePaintImageMode(imageStage.mode);imageHint();}});
input('cancel-image').addEventListener('click',()=>{cancel();clearImage();say('Image placement cancelled · existing paint kept');});
input('project-image').addEventListener('click',()=>{cancel();if(!imageStage)return;try{const s=imageStage;if(s.surface&&!s.frame)throw Error('Pick a visible surface first');const done=s.surface?(surfacePreview()&&controller.applyImagePreview()):controller?.projectImage(s.source,s.placement,{replace:s.replace,name:s.name});if(done){clearImage();syncLayers();say('Image applied · source retained · Edit image / On surface repositions it · Undo/Redo keeps Paint open');}}catch(error){input('image-status').textContent=error.message;say('Image: '+error.message);}});

for(const [name,fn] of [['pointerdown',down],['pointermove',move],['pointerup',up],['pointercancel',up]])window.addEventListener(name,fn,{capture:true,passive:false});
canvas?.addEventListener('lostpointercapture',e=>{if(contact===e.pointerId)cancel();});
window.addEventListener('blur',()=>{cancel();touches.clear();});window.addEventListener('resize',()=>{cancel();hideTools();});document.addEventListener('visibilitychange',()=>{if(document.hidden){cancel();touches.clear();}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&controller?.active){cancel();say('UV Paint stays active · use Done to exit');}});window.addEventListener('boxlab-tool-session-change',e=>{if(e.detail?.id==='uv-paint'&&e.detail.active===false)close();});
document.querySelectorAll('#selectionModes button').forEach(button=>button.addEventListener('click',event=>{if(!controller?.active)return;event.preventDefault();event.stopImmediatePropagation();say('Use Done to leave UV Paint before changing selection mode');},true));
window.addEventListener('pagehide',e=>{if(e.persisted){cancel();return;}disposed=true;close();});
for(const k of ['colour','radius','hardness','opacity','pressure','brush'])input(k).addEventListener('input',cancel);
input('done').addEventListener('click',()=>{close();say('UV Paint closed · strokes kept · Save .boxlab to keep paint');});
for(const k of ['undo','redo'])input(k).addEventListener('click',()=>{document.querySelector('#'+k+'Btn')?.click();});
const button=document.createElement('button');button.id='viewportPaintBtn';button.type='button';button.textContent='UV PAINT';button.title='Paint the selected native UV object';button.setAttribute('aria-pressed','false');button.addEventListener('click',()=>open());
function mountPaintEntry(){const bar=document.querySelector('#viewportSelectionControls');if(!bar)return false;if(button.parentNode!==bar)bar.appendChild(button);return true;}
if(!mountPaintEntry())menu?.insertBefore(button,menu.querySelector('.drawer-subtitle'));
window.addEventListener('boxlab-bridge-state',mountPaintEntry);window.addEventListener('boxlab-object-manager-ready',mountPaintEntry);
const entryObserver=typeof MutationObserver==='function'?new MutationObserver(()=>{if(mountPaintEntry())entryObserver.disconnect();}):null;entryObserver?.observe(document.querySelector('#viewportWrap')||document.body,{childList:true,subtree:true});
// The original history owner brackets the whole scene restore, including body rebuild.
// Close before capture so transient strokes/images cannot leak into scene history.
function beforeHistory(){const restore=controller?.active?{...controller.state,paintPage:panel.dataset.page}:historyContext;if(!restore)return;const id=manager()?.activeId;cancel();close();const token=opening;return ()=>{if(disposed||opening!==token||manager()?.activeId!==id||tools()?.isActive?.())return;void open(restore);};}
globalThis.__boxlabViewportPaint={open:()=>open(),beforeHistory,close,cancel:close,showTools,backgroundHoldAllowed,isBackgroundPoint,beginBrushResize,updateBrushResize,endBrushResize,get active(){return !!controller?.active;}};
